.pc-banner-inner-flex {
  display: flex;
  flex-wrap: wrap; // CRITICAL FOR FLUID LAYOUT
  align-items: center;
  gap: 8px;
  width: 100%;
}

.pc-banner-text {
  @include pixelated;
  font-size: 8px;
  font-weight: 400 !important; // Remove bold
  line-height: 1.4;
  color: var(--white);
  flex: 1 1 180px; 
  min-width: 0;
  white-space: normal; // Ensure wrapping
  word-break: break-word;

  span { 
    color: var(--yellow);
    font-weight: normal !important;
  }

  .text-highlight { 
    color: var(--yellow); 
    @include pixelated;
    font-size: 8px !important; // Match base text size
    font-weight: normal !important;
    display: block;
    margin-bottom: 4px;
    white-space: normal;
  }
}

.pc-banner-spawns {
  display: flex;
  align-items: center;
  margin-left: auto; // Push to right if sharing row
  min-height: 32px;
  flex-shrink: 0;
  gap: 8px;

  .sprite-container {
    position: relative;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    will-change: transform, filter, opacity;
  filter: Drop-Shadow(0 4px 6px Rgba(0,0,0,0.4));
  }

  img {
    width: 32px; 
    height: 32px;
    object-fit: contain;
    @include sprite-render;
    transition: none !important;
    transform: Translatez(0);
  }

  .sprite-fallback {
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    background: Rgba(255, 255, 255, 0.05);
    border-radius: 6px;
    color: $muted;
  }

  .sprite-counter {
    margin-left: 4px;
    @include pixelated;
    font-size: 8px;
    color: var(--yellow);
    background: Rgba(0, 0, 0, 0.4);
    padding: 4px 6px;
    border-radius: 6px;
    border: 1px solid Rgba(255, 217, 61, 0.2);
    @include pixelated;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
  }
}

.event-banner {
  &.active {
    background: Linear-Gradient(135deg, 
      Rgba(255, 214, 10, 0.2) 0%, 
      Rgba(15, 23, 42, 0.95) 100%
    ) !important;
    border-color: Rgba(255, 214, 10, 0.8) !important;
    box-shadow: 
      0 10px 30px Rgba(0, 0, 0, 0.6),
      0 0 20px Rgba(255, 214, 10, 0.25);

    .pc-banner-title { color: var(--yellow); opacity: 1; }
    .pc-banner-icon { 
      background: Rgba(255, 214, 10, 0.3);
      color: var(--yellow); 
      box-shadow: 0 0 15px Rgba(255, 214, 10, 0.4);
    }

    &::after {
      background: Linear-Gradient(180deg, Rgba(255, 214, 10, 0.3), Rgba(255, 214, 10, 0.05));
    }

    &:hover {
      background: Linear-Gradient(135deg, 
        Rgba(255, 214, 10, 0.3) 0%, 
        Rgba(30, 41, 59, 0.95) 100%
      ) !important;
      border-color: var(--yellow) !important;
      box-shadow: 
        0 0 0 2px var(--yellow), 
        0 15px 40px Rgba(0, 0, 0, 0.7), 
        0 0 35px Rgba(255, 214, 10, 0.6);
    }
  }
}

.pixelated { 
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  image-rendering: -webkit-optimize-contrast;
  -ms-interpolation-mode: nearest-neighbor;
}

@media (max-width: 1100px) {
  /* Removed rogue global HUD overrides */
}

@media (max-width: 768px) {
  .pc-split-container {
    flex-direction: column;
    height: auto;
  }
  .pc-left {
    flex: 1;
    min-height: 120px;
  }
  .pc-right {
    flex: 1;
  }

  .pc-banner-text {
    flex: 1 1 120px; // More flexible for small screens
  }

  .pc-banner { 
    height: auto; 
    min-height: 70px;
    padding: 10px 12px;
  }

  .pc-banner-icon {
    width: 36px;
    height: 36px;
    font-size: 18px;
  }
}
</style>

